(()=>{const e=document.querySelector("[data-tdd-view]");if(!e||!navigator.sendBeacon||navigator.webdriver)return;const t=()=>navigator.sendBeacon(e.dataset.endpoint,new Blob([JSON.stringify({id:Number(e.dataset.tddView)})],{type:"application/json"})),i=()=>{document.visibilityState==="visible"?setTimeout(t,3e3):document.addEventListener("visibilitychange",()=>document.visibilityState==="visible"&&setTimeout(t,3e3),{once:!0})};document.prerendering?document.addEventListener("prerenderingchange",i,{once:!0}):i()})();
